mapper.select:

where del_flag = '0'
 and month_plan_aps_version = #{monthPlanApsVersion}
         and sap_code = #{sapCode}
         and embryo_code = #{embryoCode}
         and plan_modify_qty = #{planModifyQty}
         and adjust_source = #{adjustSource}
         and bom_data_version = #{bomDataVersion}

WITH temp_table AS (
SELECT #{item.embryoCode,jdbcType=VARCHAR} embryo_code, #{item.bomDataVersion,jdbcType=VARCHAR} bom_data_version FROM dual
) select sum(NVL(plan_modify_qty, 0 )) as plan_modify_qty, embryo_code, BOM_DATA_VERSION from t_cx_month_plan_adjust where (embryo_code, bom_data_version) IN ( select embryo_code, bom_data_version from temp_table) and del_flag = '0' AND month_plan_aps_version = #{apsVersion,jdbcType=VARCHAR} GROUP BY EMBRYO_CODE, BOM_DATA_VERSION

mapper.update:
update t_cx_month_plan_adjust
month_plan_aps_version = #{monthPlanApsVersion}, sap_code = #{sapCode}, embryo_code = #{embryoCode}, plan_modify_qty = #{planModifyQty}, adjust_source = #{adjustSource}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, remark = #{remark},
where id = #{id}
